  "segment_function": "To analyze Hannah Arendt's concept of world alienation as the central problem of modernity and its relation to political and philosophical traditions.",
  "claims": [
    {
      "claim": "For Arendt, the central issue of the modern age is world alienation rather than self-alienation.",
      "claim_type": "author_position",
      "supporting_excerpt": "، اﺻﻠﯽ دوران ﻣﺪرنﻪ ﻣﺴﺌﻠ، ﺑﺮ بۆ آرﻧﺖ »ﺟﻬـﺎن از ﺑﯿﮕـﺎﻧﮕﯽ «اﺳـﺖ . او در ﮐﺘـﺎب »وﺿـﻊ ﺑﺸﺮ«دﻫﺪ ﮐﻪ »دوران ﻪ ﺑﯿﮕﺎﻧﮕﯽ و ﻧﻪ از ﺧﻮد ﺑﯿﮕـﺎﻧﮕﯽ دارد ﺑـﻪ ﻣﺸﺨﺼـ    از ﺟﻬﺎن ﺷﻮد ﻣﺪرن ﺗﺒﺪﯾﻞ ﻣﯽ «",
      "support_kind": "direct",
      "confidence": 1.0
    },
    {
      "claim": "World alienation results in the loss of the common and public world, isolating individuals into private spheres and inwardness.",
      "claim_type": "author_position",
      "supporting_excerpt": "ﺟﻬـﺎن ، ﻫﻤﭽﻨﯿﻦ ﯾﮑﯽ دﯾﮕﺮ از ﻋﻮاﻗﺐ ﺑﯿﮕﺎﻧﮕﯽ از ﺟﻬﺎن اﯾﻦ اﺳﺖ ﮐﻪ ﻓﺮد. ﮐﻨﺪ ﻧﯿﺰ ﺧﺼﻮﺻـﯽ ﺧـﻮد   ةﺣـﻮز ﺳـﻮي ﺧـﻮد و    از ﺟﻬﺎن ﺑـﻪ  دﻫﺪ و ﻣﺸﺘﺮك و ﻋﻤﻮﻣﯽ را از دﺳﺖ ﻣﯽ",
      "support_kind": "direct",
      "confidence": 1.0
    }
  ],
  "definitions": [
    {
      "term": "ﺟﻬﺎن ﺑﯿﮕﺎﻧﮕﯽ (World alienation)",
      "definition": "The condition in the modern age where people lose their connection to a common, intersubjectively constituted world, resulting in the loss of meaning of existence and shared reality."
    }
  ],
  "distinctions": [
    {
      "item_a": "ﺑﯿﮕﺎﻧﮕﯽ از ﺟﻬﺎن (World alienation)",
      "item_b": "ﺑﯿﮕﺎﻧﮕﯽ از ﺧﻮد (Self-alienation)",
      "distinction": "Arendt argues that modernity is characterized by alienation from the world rather than alienation from the self."
    }
  ],
  "examples": [],
  "objections": [],
